body { font-family: sans-serif; background: #090d16; color: #f1f5f9; display: flex; justify-content: center; align-items: center; min-height: 100vh; margin: 0; }
.game-wrapper { background: #131b2e; border: 1px solid #233150; border-radius: 1rem; padding: 2rem; text-align: center; max-width: 440px; width: 100%; }
.turn-indicator { color: #00f0ff; font-weight: bold; }

.game-footer { border-top: 1px solid #233150; padding-top: 1rem; display: flex; flex-direction: column; gap: 0.75rem; }
.restart-button { padding: 0.5rem 1rem; background: #090d16; border: 1px solid #233150; color: #fff; border-radius: 0.5rem; cursor: pointer; align-self: center; }
.stats-row { display: flex; justify-content: space-around; font-size: 0.85rem; color: #94a3b8; }

let currentPlayer = 'X';
let board = ['', '', '', '', '', '', '', '', ''];
let active = true;
const winConditions = [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
function handleClick(e) {
  const idx = parseInt(e.target.dataset.index);
  if (board[idx] !== '' || !active) return;
  board[idx] = currentPlayer;
  e.target.textContent = currentPlayer;
  for (let c of winConditions) {
    if (board[c[0]] && board[c[0]] === board[c[1]] && board[c[0]] === board[c[2]]) {
      active = false;
      return;
    }
  }
  if (!board.includes('')) active = false;
  currentPlayer = currentPlayer === 'X' ? 'O' : 'X';
}
document.querySelectorAll('.cell').forEach(c => c.addEventListener('click', handleClick));

finalFiles.content:
:root {
  --bg: #090d16;
  --card: #131b2e;
  --border: #233150;
  --text: #f1f5f9;
  --text-muted: #94a3b8;
  --color-x: #00f0ff;
  --color-o: #f43f5e;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: sans-serif;
  background-color: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}
.game-wrapper {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 1.25rem;
  width: 100%;
  max-width: 440px;
  padding: 2rem;
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.5);
  text-align: center;
}
.app-title {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--text);
  margin-bottom: 0.5rem;
}
.turn-indicator {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--color-x);
}
.game-board {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
  margin: 0 auto 1.25rem auto;
  max-width: 320px;
}
.cell {
  background: #090d16;
  border: 2px solid var(--border);
  border-radius: 0.75rem;
  aspect-ratio: 1;
  font-size: 2.25rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--text);
}
.game-status {
  font-size: 1rem;
  font-weight: 700;
  min-height: 1.5rem;
  margin-bottom: 1rem;
}
.game-footer {
  border-top: 1px solid var(--border);
  padding-top: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.restart-button {
  background: #090d16;
  border: 1px solid var(--border);
  color: var(--text);
  padding: 0.625rem 1.25rem;
  border-radius: 0.5rem;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  align-self: center;
}
.stats-row {
  display: flex;
  justify-content: space-around;
  font-size: 0.8125rem;
  color: var(--text-muted);
}

const cells = document.querySelectorAll('.cell');
const turnIndicator = document.getElementById('turn-indicator');
const statusText = document.getElementById('game-status');
const restartBtn = document.getElementById('restart-btn');
let currentPlayer = 'X';
let boardState = ['', '', '', '', '', '', '', '', ''];
let isGameActive = true;
const winConditions = [
  [0, 1, 2], [3, 4, 5], [6, 7, 8],
  [0, 3, 6], [1, 4, 7], [2, 5, 8],
  [0, 4, 8], [2, 4, 6]
];
function handleCellClick(e) {
  const idx = parseInt(e.target.dataset.index);
  if (boardState[idx] !== '' || !isGameActive) return;
  boardState[idx] = currentPlayer;
  e.target.textContent = currentPlayer;
  for (let c of winConditions) {
    if (boardState[c[0]] && boardState[c[0]] === boardState[c[1]] && boardState[c[0]] === boardState[c[2]]) {
      statusText.textContent = `Player ${currentPlayer} Wins!`;
      isGameActive = false;
      return;
    }
  }
  if (!boardState.includes('')) {
    statusText.textContent = 'Draw Game!';
    isGameActive = false;
    return;
  }
  currentPlayer = currentPlayer === 'X' ? 'O' : 'X';
  turnIndicator.textContent = `Player ${currentPlayer}'s Turn`;
}
cells.forEach(cell => cell.addEventListener('click', handleCellClick));
restartBtn.addEventListener('click', () => {
  currentPlayer = 'X';
  boardState = ['', '', '', '', '', '', '', '', ''];
  isGameActive = true;
  statusText.textContent = '';
  turnIndicator.textContent = "Player X's Turn";
  cells.forEach(c => c.textContent = '');
});
